'use client';

import { useEffect, useState } from 'react';
import { CalendarDays, FileText, Link2, MapPin, UserPlus, UserRoundCheck } from 'lucide-react';
import { AppShell, Avatar } from '@/components/doc-campus-shell';
import { api, Post, User } from '@/lib/doc-campus-api';

type Profile = User & { followersCount: number; followingCount: number; isSelf: boolean; isFollowing: boolean };
type FeedResponse = { items: Post[] };

export default function ProfilePage() {
  const [profile, setProfile] = useState<Profile | null>(null); const [posts, setPosts] = useState<Post[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  async function load() { try { const summary = await api<{ username: string }>('/api/users/me/summary'); const [data, postData] = await Promise.all([api<Profile>(`/api/users/${summary.username}`), api<FeedResponse>(`/api/posts/user/${summary.username}?limit=20`)]); setProfile(data); setPosts(postData.items); } catch (caught) { setError(caught instanceof Error ? caught.message : 'Could not load profile'); } finally { setLoading(false); } }
  useEffect(() => { load(); }, []);
  async function toggleFollow() { if (!profile) return; await api(`/api/users/${profile.username}/follow`, { method: profile.isFollowing ? 'DELETE' : 'POST' }); setProfile({ ...profile, isFollowing: !profile.isFollowing, followersCount: profile.followersCount + (profile.isFollowing ? -1 : 1) }); }
  if (loading) return <AppShell><div className="loading-stack"><div /><div /></div></AppShell>;
  if (error || !profile) return <AppShell><div className="empty-state">{error || 'Profile not found'}</div></AppShell>;
  return <AppShell user={profile}><div className="profile-page"><section className="profile-hero"><div className="profile-hero-cover" /><div className="profile-hero-content"><Avatar username={profile.username} src={profile.avatarUrl} large /><div className="profile-heading"><p className="eyebrow">DOC-CAMPUS MEMBER</p><h1>{profile.username}</h1><p>{profile.bio || 'Building a thoughtful learning trail, one document at a time.'}</p><div className="profile-meta"><span><CalendarDays size={14} /> Joined {profile.createdAt ? new Date(profile.createdAt).toLocaleDateString(undefined, { month: 'short', year: 'numeric' }) : 'recently'}</span><span><MapPin size={14} /> Your campus</span></div></div>{profile.isSelf ? <button className="primary-button profile-follow"><UserRoundCheck size={16} /> Your profile</button> : <button className="primary-button profile-follow" onClick={toggleFollow}>{profile.isFollowing ? <><UserRoundCheck size={16} /> Following</> : <><UserPlus size={16} /> Follow</>}</button>}</div><div className="profile-stats"><div><strong>{posts.length}</strong><span>Documents</span></div><div><strong>{profile.followersCount}</strong><span>Followers</span></div><div><strong>{profile.followingCount}</strong><span>Following</span></div></div></section><div className="profile-body"><section><div className="section-heading"><div><p className="eyebrow">SHARED RESOURCES</p><h2>Document trail</h2></div><span>{posts.length} uploads</span></div>{posts.length ? posts.map((post) => <a className="profile-post" key={post.id} href={post.fileUrl} target="_blank" rel="noreferrer"><span className={`file-icon ${post.fileType}`}><FileText size={20} /></span><span><strong>{post.description || `${post.fileType.toUpperCase()} document`}</strong><small>Shared {new Date(post.createdAt).toLocaleDateString()}</small></span><Link2 size={17} /></a>) : <div className="empty-state"><FileText size={24} /><p>No shared documents yet.</p></div>}</section><aside className="profile-note"><p className="eyebrow">YOUR SPACE</p><h3>A profile that feels like a living notebook.</h3><p>Keep your bio current and let people discover what you are learning.</p></aside></div></div></AppShell>;
}