'use client';

import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { Bell, Bookmark, FileText, Home, LogOut, Menu, Search, Sun, UserRound, X } from 'lucide-react';
import { useState } from 'react';
import { logout } from '@/lib/doc-campus-api';

type ShellProps = { user?: { username: string; avatarUrl?: string | null }; children: React.ReactNode };

function Avatar({ username, src, large = false }: { username: string; src?: string | null; large?: boolean }) {
  return src ? <img src={src} alt="" className={`avatar ${large ? 'avatar-lg' : ''}`} /> : <span className={`avatar avatar-fallback ${large ? 'avatar-lg' : ''}`}>{username.slice(0, 1).toUpperCase()}</span>;
}

export function AppShell({ user, children }: ShellProps) {
  const router = useRouter();
  const pathname = usePathname();
  const [menuOpen, setMenuOpen] = useState(false);
  const [search, setSearch] = useState('');
  async function signOut() { await logout(); router.push('/sign-in'); }
  return <div className="app-frame">
    <header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle navigation"><Menu size={20} /></button><Link href="/feed" className="brand"><span className="brand-mark">D</span><span>Doc<span>Campus</span></span></Link><label className="search-box"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search people, documents, topics..." /><kbd>⌘ K</kbd></label><nav className="top-actions"><button className="icon-button" aria-label="Light mode"><Sun size={18} /></button><button className="icon-button notification" aria-label="Notifications"><Bell size={18} /><i /></button><button className="profile-trigger" onClick={() => router.push('/profile')}><Avatar username={user?.username || 'D'} src={user?.avatarUrl} /></button></nav></header>
    <div className={`mobile-nav ${menuOpen ? 'open' : ''}`}><button onClick={() => setMenuOpen(false)}><X size={18} /></button><Link href="/feed"><Home size={16} /> Feed</Link><Link href="/profile"><UserRound size={16} /> My profile</Link><button onClick={signOut}><LogOut size={16} /> Sign out</button></div>
    <main className="shell-content"><aside className="left-rail"><div className="rail-label">Workspace</div><Link className={pathname === '/feed' ? 'active' : ''} href="/feed"><Home size={17} /> Feed</Link><Link href="/profile"><UserRound size={17} /> My profile</Link><Link href="/saved"><Bookmark size={17} /> Saved documents</Link><div className="rail-divider" /><div className="rail-label">Explore</div><button><FileText size={17} /> Study notes</button><button><Search size={17} /> Discover people</button><div className="rail-bottom"><button onClick={signOut}><LogOut size={17} /> Sign out</button></div></aside><section className="page-column">{children}</section></main>
  </div>;
}

export { Avatar };